"""Reproduce MeanFlow teaching SVGs; result values from course PDF Table 2."""
from pathlib import Path
from html import escape
out=Path(__file__).resolve().parents[1]/'public/figures/meanflows'
out.mkdir(parents=True,exist_ok=True)
def text(x,y,s,size=19):
    return f'<text x="{x}" y="{y}" font-size="{size}">{escape(s)}</text>'
def box(x,y,w,a,b,color='#ddd9fa'):
    return f'<rect x="{x}" y="{y}" width="{w}" height="86" rx="12" fill="{color}" stroke="#71849a"/>'+text(x+14,y+32,a)+text(x+14,y+62,b,16)
def arrow(x,y,a,b):
    return f'<path d="M{x} {y} L{a} {b}" stroke="#53677d" stroke-width="3" fill="none" marker-end="url(#a)"/>'
def svg(name,title,desc,body,h=440):
    (out/f'{name}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 940 {h}" role="img" aria-labelledby="t d"><title id="t">{escape(title)}</title><desc id="d">{escape(desc)}</desc><defs><marker id="a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8" fill="#53677d"/></marker></defs><rect width="940" height="{h}" rx="18" fill="#f3f6fb"/><g font-family="Arial,sans-serif" fill="#17304b">'+text(28,43,title,25)+body+'</g></svg>')
svg('problem','01 / Local direction or complete displacement?','Schematic curved marginal path, local tangent and endpoint chord.', '<path d="M790 130 C540 100 670 340 180 330" fill="none" stroke="#73859d" stroke-width="5"/>'+arrow(790,130,420,85)+'<path d="M790 130 L180 330" stroke="#168373" stroke-width="4" marker-end="url(#a)"/>'+text(560,85,'Local tangent',18)+text(380,350,'Backward displacement = −(t − r)u',18)+text(725,170,'Noise zₜ',19)+text(80,375,'Destination zᵣ',19)+text(30,417,'Straight training pairs can induce curved marginal trajectories. Schematic.',18))
svg('interval','02 / One state, two different destination questions','Two interval queries return same-shaped average-velocity tensors.',box(30,170,250,'Current state zₜ','32 × 32 × 4 latent')+arrow(290,200,345,133)+arrow(290,225,345,303)+box(355,90,270,'uθ(zₜ, r = 0.5, t = 1)','Summarize half the interval')+box(355,260,270,'uθ(zₜ, r = 0, t = 1)','Summarize all the interval')+arrow(635,133,670,133)+arrow(635,303,670,303)+box(680,90,230,'Average velocity','32 × 32 × 4')+box(680,260,230,'Average velocity','32 × 32 × 4')+text(30,410,'A velocity tensor is not an average image. Destination time changes the question.',18))
svg('training','03 / Training: predict, differentiate, build target','Unguided functional architecture with same-network JVP and detached target.',box(30,85,260,'A · Latent x + noise ε','VAE latent: 32 × 32 × 4','#d4eee7')+arrow(300,128,335,128)+box(345,85,250,'B · Interpolate','zₜ, r, t; vₜ = ε − x','#d4eee7')+arrow(605,128,640,128)+box(650,85,260,'C · Transformer uθ','Average-velocity prediction')+arrow(470,182,470,245)+box(330,255,280,'D · Same-network JVP','Input tangent (vₜ, 0, 1)')+arrow(470,350,470,405)+box(330,415,280,'E · Target, then detach','vₜ − (t − r) × JVP','#d4eee7')+box(650,415,260,'F · Squared residual','Updates network weights','#ffe6cb')+arrow(620,458,640,458)+arrow(780,182,780,405)+text(30,553,'Purple: learned model    Green: data / target    Orange: optimization',18)+text(30,586,'No integrated trajectory labels. Stop-gradient applies to the entire target.',18),620)
svg('numbers','04 / A scalar example through the training boxes','Synthetic scalar example with total derivative 2 and loss 0.25.',box(30,95,260,'A → B · x = 2, ε = 6','t = 0.75, r = 0.25')+arrow(300,138,335,138)+box(345,95,250,'B · zₜ = 5, vₜ = 4','Interval = 0.5')+arrow(605,138,640,138)+box(650,95,260,'C · Predict uθ = 2.5','∂z uθ = 0.25; ∂t uθ = 1')+box(30,260,260,'D · JVP = 2','0.25 × 4 + 1')+arrow(300,303,335,303)+box(345,260,250,'E · Target = 3','4 − 0.5 × 2; detached','#d4eee7')+arrow(605,303,640,303)+box(650,260,260,'F · Loss = 0.25','(2.5 − 3)²; unweighted','#ffe6cb')+text(30,409,'The target is frozen for this update, but changes when the model changes.',18))
svg('sampling','05 / One flow-network call at inference','Fixed trained weights map noise to average velocity; subtract and decode.',box(30,100,260,'Gaussian ε + class c','Set destination 0, time 1','#d4eee7')+arrow(300,143,335,143)+box(345,100,250,'Trained uθ(ε, 0, 1 | c)','One network evaluation')+arrow(605,143,640,143)+box(650,100,260,'Subtract from ε','ẑ₀ = ε − uθ')+arrow(780,196,780,255)+box(650,270,260,'Fixed VAE decoder','Latent → 256 × 256 image','#d4eee7')+text(30,291,'No derivative or optimizer at inference.',20)+text(30,327,'Guided model: guidance learned into the field.',18)+text(30,407,'1-NFE counts flow-network calls; VAE decoding still requires computation.',18))
svg('steps','06 / Carry the new state into the next interval','One jump versus two jumps; exact displacements add along the same trajectory.',box(30,90,210,'Start z₁','Time 1','#d4eee7')+arrow(250,133,645,133)+text(325,111,'One call: uθ(z₁, 0, 1)',18)+box(655,90,250,'Endpoint z₀','Time 0','#d4eee7')+box(30,260,210,'Start z₁','Time 1','#d4eee7')+arrow(250,303,335,303)+box(345,260,250,'Intermediate z₀.₅','Call 1: uθ(z₁, 0.5, 1)')+arrow(605,303,645,303)+box(655,260,250,'Endpoint z₀','Call 2: uθ(z₀.₅, 0, 0.5)')+text(30,404,'Exact field: equal endpoints. Learned field: agreement is not guaranteed.',18))
body=text(30,88,'ImageNet 256 × 256 · class conditional · FID-50K ↓ · Table 2',18)
for i,(label,val,color) in enumerate([('iCT-XL/2',34.24,'#73859d'),('Shortcut-XL/2',10.60,'#73859d'),('MeanFlow-XL/2',3.43,'#168373')]):
    y=120+i*75
    body+=text(30,y+27,label)+f'<rect x="245" y="{y}" width="{val*16}" height="38" rx="5" fill="{color}"/>'+text(255+val*16,y+27,f'{val:.2f}')
body+=text(245,365,'0',16)+text(405,365,'10',16)+text(565,365,'20',16)+text(725,365,'30',16)+text(30,410,'All three: 1-NFE. Guidance where applicable. Different training configurations.',17)
svg('results','07 / Reported one-call generation quality','Reported FID: iCT 34.24, Shortcut 10.60, MeanFlow XL/2 3.43.',body)
